import { GraduationCap, LifeBuoy, type LucideIcon } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { NavLink, useParams } from 'react-router-dom';
import { hrefFor } from '@/features/footer/content';
import { useHeaderLinks } from './content';
import { navItemClass, type NavVariant } from './navStyles';

/**
 * The built-in entries' wording, which stays in the app.
 *
 * An administrator arranges the header; the words come from the same bundles as the rest of the
 * site, so reordering the bar never costs the Japanese or Russian translation. ("knowledge" reads
 * from the older `nav.tools` key, which is where that label has always lived.)
 */
const LABEL_KEYS: Record<string, string> = {
  home: 'nav.home',
  how: 'nav.how',
  services: 'nav.services',
  coverage: 'nav.coverage',
  knowledge: 'nav.tools',
  contact: 'nav.contact',
};

/** Only the two entries that carried a glyph before; the rest read as plain words. */
const ICONS: Record<string, LucideIcon> = {
  knowledge: GraduationCap,
  contact: LifeBuoy,
};

/**
 * The site header's own entries, in the order an administrator arranged them.
 *
 * Rendered without a surrounding `<nav>` so the header can put the account entries in the same
 * landmark. Three kinds of destination, told apart by the stored string exactly as the footer does
 * it: an anchor is a plain link so the jump works from any page, an in-app path is a router link
 * that can show as current, and an external address opens in its own tab.
 */
export function SiteNavLinks({ isSignedIn, variant }: { isSignedIn: boolean; variant: NavVariant }) {
  const { t } = useTranslation();
  const { lang = 'en' } = useParams<{ lang: string }>();
  const links = useHeaderLinks(isSignedIn);

  return links.map((link) => {
    const Icon = link.key ? ICONS[link.key] : undefined;
    const labelKey = link.key ? LABEL_KEYS[link.key] : undefined;
    const label = link.label?.trim() || (labelKey ? t(labelKey) : '');

    // A built-in entry this version of the app does not know would otherwise draw a blank.
    if (!label) return null;

    const target = hrefFor(link.url, lang);
    const content = (
      <>
        {Icon ? (
          <Icon size={16} aria-hidden className="shrink-0" />
        ) : (
          // Stacked in the panel, a glyph-less entry keeps its label in line with the others.
          variant === 'panel' && <span className="size-4 shrink-0" aria-hidden />
        )}
        <span>{label}</span>
      </>
    );

    if (target.to) {
      return (
        <NavLink
          key={link.id}
          to={target.to}
          // "Home" points at the landing page, which is the prefix of every other route.
          end={target.to === `/${lang}` || target.to === `/${lang}/`}
          className={({ isActive }) => navItemClass(variant, isActive)}
        >
          {content}
        </NavLink>
      );
    }

    return (
      <a
        key={link.id}
        href={target.href}
        className={navItemClass(variant, false)}
        {...(target.external ? { target: '_blank', rel: 'noopener noreferrer' } : {})}
      >
        {content}
      </a>
    );
  });
}
